```python
PARAMS = {
    "L":   (2.0, 1.0, 6.0),     # channel length of the Schmitt core (limits crowbar current)
    "Wn":  (0.6, 0.42, 3.0),    # NMOS input stack width
    "Wp":  (2.0, 0.5, 8.0),     # PMOS input stack width (weak, high-|Vt| pfet)
    "kn":  (2.5, 0.5, 8.0),     # Wnf/Wn  -> raises vth_hi
    "kp":  (2.5, 0.5, 8.0),     # Wpf/Wp  -> lowers vth_lo
    "Linv": (1.0, 0.15, 4.0),   # output inverter length
}

def design(p, lut, spec):
    VDD = 1.8
    L, Wn, Wp = p["L"], p["Wn"], p["Wp"]
    Wnf, Wpf = max(0.42, p["kn"] * Wn), max(0.42, p["kp"] * Wp)
    Li = p["Linv"]

    n = Netlist("vin vout vdd vss")
    # NMOS stack: M1 (bottom) and M2 (top), internal node x; M3 is the feedback device from vdd to x
    n.M("M1", "x", "vin", "vss", "vss", "nfet", Wn, L)
    n.M("M2", "z", "vin", "x", "vss", "nfet", Wn, L)
    n.M("M3", "vdd", "z", "x", "vss", "nfet", Wnf, L)
    # PMOS stack: M4 (top) and M5 (bottom), internal node y; M6 is the feedback device from y to vss
    n.M("M4", "y", "vin", "vdd", "vdd", "pfet", Wp, L)
    n.M("M5", "z", "vin", "y", "vdd", "pfet", Wp, L)
    n.M("M6", "vss", "z", "y", "vdd", "pfet", Wpf, L)
    # output inverter: z is inverted, so vout is non-inverting
    n.M("M7", "vout", "z", "vss", "vss", "nfet", 0.42, Li)
    n.M("M8", "vout", "z", "vdd", "vdd", "pfet", 1.0, Li)

    def In(W, vgs, vds, vsb=0.0):
        if vgs <= 0 or vds <= 0:
            return 0.0
        return abs(lut.op("n", W, L, vgs, max(vds, 0.02), vsb)["Id"])

    def Ip(W, vsg, vsd, vbs=0.0):
        if vsg <= 0 or vsd <= 0:
            return 0.0
        return abs(lut.op("p", W, L, vsg, max(vsd, 0.02), vbs)["Id"])

    vtn = lut.op("n", Wn, L, 0.8, 0.6)["vth"]
    vtp = abs(lut.op("p", Wp, L, 0.8, 0.6)["vth"])

    def bisect(f, a, b, it=40):
        fa = f(a)
        for _ in range(it):
            m = 0.5 * (a + b)
            fm = f(m)
            if (fm > 0) == (fa > 0):
                a, fa = m, fm
            else:
                b = m
        return 0.5 * (a + b)

    # vth_hi: M2 turns on when x = vin - vtn, at which point M1 must sink M3's current
    def fhi(vin):
        x = max(vin - vtn, 0.02)
        return In(Wn, vin, x) - In(Wnf, VDD - x, VDD - x, x)
    vth_hi = bisect(fhi, vtn + 0.05, VDD)

    # vth_lo: M5 turns on when y = vin + vtp, at which point M4 must source M6's current
    def flo(vin):
        y = min(vin + vtp, VDD - 0.02)
        return Ip(Wp, VDD - vin, VDD - y) - Ip(Wpf, y, y, VDD - y)
    vth_lo = bisect(flo, 0.0, VDD - vtp - 0.02)

    # power: crowbar current through M3/M1 while rising (vtn..vth_hi)
    # and through M4/M6 while falling (vth_lo..VDD-vtp)
    grid = np.linspace(0.0, VDD, 61)
    ir = []
    for v in grid:
        if vtn < v < vth_hi:
            x = max(v - vtn, 0.02)
            ir.append(min(In(Wn, v, 0.3), In(Wnf, VDD - x, VDD - x, x)))
        else:
            ir.append(0.0)
    i_f = []
    for v in grid:
        if vth_lo < v < VDD - vtp:
            y = min(v + vtp, VDD - 0.02)
            i_f.append(min(Ip(Wp, VDD - v, 0.3), Ip(Wpf, y, y, VDD - y)))
        else:
            i_f.append(0.0)
    p_avg = VDD * 0.5 * (np.mean(ir) + np.mean(i_f)) * 1.2  # +20% for the inverter and switching

    return n, {"vth_hi": vth_hi, "vth_lo": vth_lo,
               "hysteresis": vth_hi - vth_lo, "power_avg": p_avg}
